package main

import (
	"fmt"
	"github.com/golang-jwt/jwt/v5"
	"time"
)

func main() {
	// Example token with valid and invalid claims
	validToken := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoiSm9obiBEb24iLCJleHAiOjE2NjM5MjQ1ODJ9.SflK2yR1JbV1DgqkK41Kv6h4g8V61qX61qX61qX61qX6"
	invalidToken := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoiSm9obiBEb24iLCJleHAiOjE2NjM5MjQ1ODJ9.abcdef123456"

	// Validate claims
	validateClaims := func(tokenString string) bool {
		token, err := jwt.Parse(tokenString, func(t *jwt.Token) (interface{}, error) {
			if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
				return nil, jwt.ErrInvalidKey
			}
			return []byte("secret"), nil
		})
		if err != nil {
			return false
		}
		if !token.Valid {
			return false
		}
		if claims, ok := token.Claims.(jwt.MapClaims); ok {
			if exp, ok := claims["exp"].(float64); ok {
				if time.Unix(int64(exp), 0).Before(time.Now()) {
					return false // Token expired
				}
			}
			if iss, ok := claims["iss"].(string); ok {
				if iss != "trusted-issuer" {
					return false // Invalid issuer
				}
			}
			if nbf, ok := claims["nbf"].(float64); ok {
				if time.Unix(int64(nbf), 0).After(time.Now()) {
					return false // Token not yet valid
				}
			}
		}
		return true
	}

	fmt.Println("Valid Token:", validateClaims(validToken))
	fmt.Println("Invalid Token:", validateClaims(invalidToken))
}

